class Solution {
public:
    int minRotations(string s) {
        int sum = 0;
        int curr = 0;

        for( int i = 0 ;i<s.size();i++){
            int in = s[i]-'0';
            int diff = abs(curr - in);
            sum += min(diff,10-diff);

            curr = in;
        }

        return sum ;
    }
};

class Solution {
public:
    bool checkValidString(string s) {
        int low = 0, high = 0;
        for (char c : s) {
            if (c == '(') {
                low++;
                high++;
            } else if (c == ')') {
                low--;
                high--;
            } else {
                low--;
                high++;
            }
            if (high < 0) return false;
            if (low < 0) low = 0;
        }
        return low == 0;
    }
};

class Solution {
public:
    int scoreOfParentheses(string s) {
        int score = 0, depth = 0;
        for (int i = 0; i < s.size(); ++i) {
            if (s[i] == '(') {
                ++depth;
            } else {
                --depth;
                if (s[i - 1] == '(') {
                    score += 1 << depth;
                }
            }
        }
        return score;
    }
};

class Solution {
public:
    int minAddToMakeValid(string s) {
        int A =0,B = 0;
        for( auto ch : s ){
            if( ch == '(')
                A++;
            else {
                if(A > 0){
                    A--;
                }
                else{
                    B++;}
            }      
        }
        return A+B;
    }
};

class Solution {

    void remove(string s, int sS,int dS,char o,char c,vector<string>&v){
        int b = 0;

        for( int i = sS;i<s.size();i++){
            if(s[i] == o) b++;
            else if(s[i] == c) b--;

            if(b>=0){
                continue;
            }
            for(int j = dS;j<= i;j++){
                if( s[j] == c && (j == dS || s[j-1] != c)){
                    remove(s.substr(0,j) + s.substr(j+1),i,j,o,c,v);
                }
            }
            return;
        }
        reverse(s.begin(),s.end());

        if(o =='('){
            remove(s,0,0,')','(',v);
        }
        else {
            v.push_back(s);
        }

    }
public:
    vector<string> removeInvalidParentheses(string s) {
        vector<string> v;
        remove(s,0,0,'(',')',v);
        return v;
    }
};

class Solution {
public:
    int dominantIndex(vector<int>& a) {
        int n = a.size();
        int it = distance(begin(a), max_element(begin(a), end(a)));

        nth_element(begin(a), begin(a) + n - 2, end(a));

        return a[n-2] * 2 <= a[n-1] ? it : -1;
    }
};

class Solution {
public:
    int findJudge(int n, vector<vector<int>>& trust) {
        if (trust.size() == 0 && n == 1) 
            return 1;
        vector<int> out(n+1,0);
        vector<int> in(n+1,0);
        for( int i = 0;i<trust.size();i++){
           out[trust[i][0]]++;
           in[trust[i][1]]++;
        }

        for( int i=0;i<in.size();i++){
            if(in[i] == n-1 && out[i] == 0){
                return i;
            }
        }
        return -1;
    }
};

class Solution {
public:
    int findCenter(vector<vector<int>>& edges) {
        vector<int> f = edges[0];
        vector<int> s = edges[1];

        return (f[0] == s[0] || f[0] == s[1]) ? f[0] : f[1];
    }
};
